document.addEventListener('DOMContentLoaded', () => {
    const dialog = document.getElementById('delete-confirm-dialog');
    const trigger = document.getElementById('delete-trigger');
    const cancelBtn = document.getElementById('cancel-delete');
    const confirmBtn = document.getElementById('confirm-delete');

    if (!dialog || !trigger || !cancelBtn || !confirmBtn) {
        console.error('Required elements not found');
        return;
    }

    // Open dialog
    trigger.addEventListener('click', () => {
        dialog.showModal();
        // Shift focus to the cancel button instead of the destructive action
        cancelBtn.focus();
    });

    // Close dialog on Cancel
    cancelBtn.addEventListener('click', () => {
        dialog.close();
    });

    // Handle Confirm action
    confirmBtn.addEventListener('click', () => {
        // In a real app, you would perform the delete operation here
        console.log('Image deleted!');

        // Visual feedback (optional for this task)
        const imageCard = document.querySelector('.image-preview-card');
        if (imageCard) {
            imageCard.style.opacity = '0.5';
            imageCard.style.pointerEvents = 'none';
            trigger.disabled = true;
            trigger.textContent = 'Deleted';
        }

        dialog.close();
    });

    // Close dialog when clicking on the backdrop
    dialog.addEventListener('click', (event) => {
        const rect = dialog.getBoundingClientRect();
        const isInDialog = (
            rect.top <= event.clientY &&
            event.clientY <= rect.top + rect.height &&
            rect.left <= event.clientX &&
            event.clientX <= rect.left + rect.width
        );
        if (!isInDialog) {
            dialog.close();
        }
    });
});

