:root {
    --primary-color: #2563eb;
    --primary-hover: #1d4ed8;
    --danger-color: #dc2626;
    --danger-hover: #b91c1c;
    --bg-color: #f8fafc;
    --card-bg: #ffffff;
    --text-main: #1e293b;
    --text-muted: #64748b;
    --border-color: #e2e8f0;
    --focus-ring: 0 0 0 3px rgba(37, 99, 235, 0.5);
    --focus-ring-danger: 0 0 0 3px rgba(220, 38, 38, 0.5);
}

* {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
}

body {
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif, "Apple Color Emoji", "Segoe UI Emoji", "Segoe UI Symbol";
    line-height: 1.5;
    background-color: var(--bg-color);
    color: var(--text-main);
    display: flex;
    flex-direction: column;
    min-height: 100vh;
}

.container {
    max-width: 800px;
    margin: 0 auto;
    padding: 0 1.5rem;
    width: 100%;
}

/* Skip Link */
.skip-link {
    position: absolute;
    top: -40px;
    left: 0;
    background: var(--primary-color);
    color: white;
    padding: 8px;
    z-index: 100;
    transition: top 0.2s;
    text-decoration: none;
    border-radius: 0 0 4px 0;
}

.skip-link:focus {
    top: 0;
    outline: none;
    box-shadow: var(--focus-ring);
}

/* Header & Breadcrumb */
.site-header {
    padding: 1.5rem 0;
    background: var(--card-bg);
    border-bottom: 1px solid var(--border-color);
    margin-bottom: 2rem;
}

.breadcrumb {
    list-style: none;
    display: flex;
    gap: 0.5rem;
    font-size: 0.875rem;
    color: var(--text-muted);
}

.breadcrumb li:not(:last-child)::after {
    content: "/";
    margin-left: 0.5rem;
}

.breadcrumb a {
    color: var(--primary-color);
    text-decoration: none;
}

.breadcrumb a:hover {
    text-decoration: underline;
}

/* Image Preview Card */
.image-preview-card {
    background: var(--card-bg);
    border-radius: 12px;
    overflow: hidden;
    box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
    border: 1px solid var(--border-color);
}

.image-container {
    width: 100%;
    aspect-ratio: 16 / 9;
    background: #000;
    display: flex;
    align-items: center;
    justify-content: center;
}

.preview-img {
    max-width: 100%;
    max-height: 100%;
    object-fit: contain;
}

.content {
    padding: 1.5rem;
}

.content h1 {
    font-size: 1.5rem;
    font-weight: 700;
    margin-bottom: 0.25rem;
}

.meta {
    font-size: 0.875rem;
    color: var(--text-muted);
    margin-bottom: 1.5rem;
}

/* Buttons */
.actions {
    display: flex;
    gap: 1rem;
}

.btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    padding: 0.5rem 1.25rem;
    font-size: 0.875rem;
    font-weight: 600;
    border-radius: 6px;
    cursor: pointer;
    transition: all 0.2s;
    border: 1px solid transparent;
}

.btn:focus-visible {
    outline: none;
}

.btn-secondary {
    background-color: #fff;
    border-color: var(--border-color);
    color: var(--text-main);
}

.btn-secondary:hover {
    background-color: #f1f5f9;
}

.btn-secondary:focus-visible {
    box-shadow: var(--focus-ring);
}

.btn-danger {
    background-color: var(--danger-color);
    color: white;
}

.btn-danger:hover {
    background-color: var(--danger-hover);
}

.btn-danger:focus-visible {
    box-shadow: var(--focus-ring-danger);
}

/* Dialog Styling */
dialog {
    border: none;
    border-radius: 12px;
    padding: 0;
    box-shadow: 0 20px 25px -5px rgba(0, 0, 0, 0.1), 0 10px 10px -5px rgba(0, 0, 0, 0.04);
    max-width: 400px;
    width: 90%;
    margin: auto;
}

dialog::backdrop {
    background: rgba(15, 23, 42, 0.5);
    backdrop-filter: blur(4px);
}

.dialog-content {
    padding: 1.5rem;
}

.dialog-content h2 {
    font-size: 1.25rem;
    margin-bottom: 0.75rem;
    color: var(--text-main);
}

.dialog-content p {
    font-size: 0.875rem;
    color: var(--text-muted);
    margin-bottom: 1.5rem;
}

.dialog-actions {
    display: flex;
    justify-content: flex-end;
    gap: 0.75rem;
}

/* Footer */
.site-footer {
    margin-top: auto;
    padding: 2rem 0;
    text-align: center;
    color: var(--text-muted);
    font-size: 0.875rem;
}

/* Responsive adjustments */
@media (max-width: 640px) {
    .actions {
        flex-direction: column;
    }
    .btn {
        width: 100%;
    }
    .dialog-actions {
        flex-direction: column-reverse;
    }
}

@media (prefers-reduced-motion: reduce) {
    * {
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.01ms !important;
        scroll-behavior: auto !important;
    }
}
document.addEventListener('DOMContentLoaded', () => {
    const dialog = document.getElementById('delete-confirm-dialog');
    const trigger = document.getElementById('delete-trigger');
    const cancelBtn = document.getElementById('cancel-delete');
    const confirmBtn = document.getElementById('confirm-delete');

    if (!dialog || !trigger || !cancelBtn || !confirmBtn) {
        console.error('Required elements not found');
        return;
    }

    // Open dialog
    trigger.addEventListener('click', () => {
        dialog.showModal();
        // Shift focus to the cancel button instead of the destructive action
        cancelBtn.focus();
    });

    // Close dialog on Cancel
    cancelBtn.addEventListener('click', () => {
        dialog.close();
    });

    // Handle Confirm action
    confirmBtn.addEventListener('click', () => {
        // In a real app, you would perform the delete operation here
        console.log('Image deleted!');

        // Visual feedback (optional for this task)
        const imageCard = document.querySelector('.image-preview-card');
        if (imageCard) {
            imageCard.style.opacity = '0.5';
            imageCard.style.pointerEvents = 'none';
            trigger.disabled = true;
            trigger.textContent = 'Deleted';
        }

        dialog.close();
    });

    // Close dialog when clicking on the backdrop
    dialog.addEventListener('click', (event) => {
        const rect = dialog.getBoundingClientRect();
        const isInDialog = (
            rect.top <= event.clientY &&
            event.clientY <= rect.top + rect.height &&
            rect.left <= event.clientX &&
            event.clientX <= rect.left + rect.width
        );
        if (!isInDialog) {
            dialog.close();
        }
    });
});
